@prefix x: <urn:regesta:22693:> .
x:coronation a rf:ActFactoid ;
    rf:factoidType rv:Appointment ;
    rf:source <urn:regesta:record:22693> ;
    rf:evidence [ a oa:TextQuoteSelector ; oa:exact "Friedrich wird am Sonntag Letare Jerusalem (März 9) in der Marienkirche von Erzbischof Arnold von Köln unter Mitwirkung anderer Bischöfe nach Ablegung des herkömmlichen Krönungseides unter Akklamation des Volkes gesalbt, gekrönt und auf den Thron Karls des Großen gesetzt" ] ;
    prov:wasAttributedTo <urn:regesta:agent:factoid-1153-2026-11-11:extraction-batch-17> ;
    rf:verificationStatus rv:unchecked .

@prefix x: <urn:regesta:22693:> .
x:consecration-muenster a rf:ActFactoid ;
    rf:factoidType rv:Appointment ;
    rf:source <urn:regesta:record:22693> ;
    rf:evidence [ a oa:TextQuoteSelector ; oa:exact "Am selben Tag wird von denselben Bischöfen auch der neue Bischof von Münster, der ebenfalls Friedrich heißt, geweiht" ] ;
    prov:wasAttributedTo <urn:regesta:agent:factoid-1153-2026-11-11:extraction-batch-17> ;
    rf:verificationStatus rv:unchecked .

@prefix x: <urn:regesta:22693:> .
x:mission-legation a rf:ActFactoid ;
    rf:factoidType rv:Mission ;
    rf:source <urn:regesta:record:22693> ;
    rf:evidence [ a oa:TextQuoteSelector ; oa:exact "Die Entsendung einer Legation, bestehend aus dem Elekten Hillin von Trier, Bischof Eberhard von Bamberg und Abt Adam von Ebrach (vgl. Reg. 72), an Papst Eugen (III.), die Stadt Rom und ganz Italien zur Anzeige der Wahl des neuen Königs wird beschlossen" ] ;
    prov:wasAttributedTo <urn:regesta:agent:factoid-1153-2026-11-11:correction-g4> ;
    rf:verificationStatus rv:unchecked .
